+        let (tx, _rx) = mpsc::unbounded_channel::<Outbound>();
+        let mut authed = true;
+        let reply = block_on(handle_request(
+            r#"{"id":"r1","type":"respond_permission","payload":{"agentId":"a1","requestId":"perm-1","optionId":"escalate"}}"#,
